import{_ as t,o,c as d,a4 as s}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"Ce que cette pile expose","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"Ce que cette pile expose","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"documentation/referent/ce-que-cette-pile-expose.md","filePath":"documentation/referent/ce-que-cette-pile-expose.md"}'),r={name:"documentation/referent/ce-que-cette-pile-expose.md"};function n(i,e,c,a,u,l){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="ce-que-cette-pile-expose" tabindex="-1">Ce que cette pile expose <a class="header-anchor" href="#ce-que-cette-pile-expose" aria-label="Permalink to &quot;Ce que cette pile expose {#ce-que-cette-pile-expose}&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Service</th><th>Rôle</th><th>Joignable depuis</th></tr></thead><tbody><tr><td><code>caddy</code></td><td>HTTPS automatique (Let&#39;s Encrypt), en-têtes de sécurité, seul frontal</td><td>Internet, ports 80 et 443 seulement</td></tr><tr><td><code>cms-admin</code></td><td>Back-office (Nuxt), sur <code>cms.&lt;votre domaine&gt;</code></td><td>Caddy seul</td></tr><tr><td><code>cms-front</code></td><td>Site public (front de démarrage, Nuxt), sur <code>www.&lt;votre domaine&gt;</code> — <strong>profil Compose <code>front</code></strong>, démarré seulement pour un profil d&#39;usage dont le thème est livré. Système de fichiers en lecture seule.</td><td>Caddy seul</td></tr><tr><td><code>cms-api</code></td><td>API Core (FastAPI) — routes publiques seulement, sous <code>cms.&lt;votre domaine&gt;/_api/</code></td><td>Caddy, <code>cms-admin</code> et <code>cms-front</code>, réseau interne</td></tr><tr><td><code>cms-scheduler</code></td><td>Tâches automatiques (purges, dépublications, ordonnancement) — même image que <code>cms-api</code>, aucun port</td><td>Personne</td></tr><tr><td><code>postgres</code></td><td>Base de données</td><td><code>cms-api</code> et <code>cms-scheduler</code> seuls, <strong>aucun port publié</strong></td></tr></tbody></table><p>L&#39;API n&#39;est <strong>jamais</strong> exposée en entier par défaut : ses routes de session (connexion, administration) ne sont joignables que depuis l&#39;intérieur du réseau de la pile. Le site public, sous <code>www.</code>, ne relaie aucune route de l&#39;API : le front l&#39;appelle sur le réseau interne, et c&#39;est lui seul qui répond aux visiteurs. Un domaine séparé, <code>api.&lt;votre domaine&gt;</code>, l&#39;expose en entier — réservé au profil « Sur mesure (headless) » ou à qui a un développeur en face (voir <a href="/teuthis-cms-distribution/documentation/referent/exposer-l-api-en-entier#exposer-lapi-en-entier">§ Exposer l&#39;API en entier</a>, plus bas).</p><p>Trois modules restent optionnels et inactifs par défaut : antivirus des dépôts, extraction documentaire (PDF scannés, fichiers Office) et intelligence artificielle locale. Aucun des trois n&#39;est nécessaire pour qu&#39;une instance fonctionne.</p>',4)])])}const f=t(r,[["render",n]]);export{m as __pageData,f as default};
